&lt;/div&gt;&lt;div style=&quot;background-color: #fff; float: right; padding: 0 0 8px 8px&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Traits_raciaux_standards_5&quot;&gt;Traits raciaux standards&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Traits_raciaux_alternatifs_6&quot;&gt;Traits raciaux alternatifs&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Bonus_alternatifs_de_classe_de_pr&#233;dilection_7&quot;&gt;Bonus alternatifs de classe de pr&#233;dilection&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Nouvelles_r&#232;gles_raciales_8&quot;&gt;Nouvelles r&#232;gles raciales&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_0&quot;&gt;Dons&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Arch&#233;types_de_classes_1&quot;&gt;Arch&#233;types de classes&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#&#201;quipement_2&quot;&gt;&#201;quipement&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Objets_magiques_3&quot;&gt;Objets magiques&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Sorts_4&quot;&gt;Sorts&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;&lt;i&gt;Voir aussi la &lt;a class=&quot;pagelink&quot; href=&quot;Vishkanya.html&quot; title=&quot;Vishkanya&quot;&gt;fiche de cr&#233;ature&lt;/a&gt; d&#39;un vishkanya standard.&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Les vishkanyas sont une race d’humano&#239;des exotiques au sang empoisonn&#233;. D’une &#233;trange beaut&#233;, ces humano&#239;des gracieux voient le monde &#224; travers leurs yeux serpentins d’or brun. Leur peau souple est couverte de toutes petites &#233;cailles, souvent vert clair, qui pr&#233;sentent parfois des motifs qui ne sont pas sans rappeler ceux des serpents. Il n’est pas possible de les qualifier de Bons ou de Mauvais, mais ayant la langue bien fourchue, ils acceptent volontiers l’or qui leur est offert pour laisser les questions de moralit&#233; aux autres.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRAITSSTANDARDS&quot; href=&quot;#TRAITSSTANDARDS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Traits raciaux standards&lt;a class=&quot;headeranchor&quot; id=&quot;Traits_raciaux_standards_5&quot; href=&quot;#Traits_raciaux_standards_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;presentation arrondi ombre espaceliste&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;+2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;, +2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;, -2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;.&lt;/b&gt; Les vishkanyas sont gracieux et &#233;l&#233;gants, mais souvent irrationnels.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Vishkanya.&lt;/b&gt; Les vishkanyas sont des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;humano&#239;des&lt;/a&gt; de sous-type &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Vishkanya.html&quot; title=&quot;Vishkanya (sous-type)&quot;&gt;vishkanya&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Taille M.&lt;/b&gt; Les vishkanyas sont des cr&#233;atures de &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures#Tableautailles.html&quot; title=&quot;taille M&quot;&gt;taille M&lt;/a&gt; et n’ont aucun bonus ni malus de taille.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Vitesse normale.&lt;/b&gt; Les vishkanyas ont une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de base&lt;/a&gt; de 9 m&#232;tres.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Vision nocturne.&lt;/b&gt; Les vishkanyas peuvent &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;voient deux fois plus loin&lt;/a&gt; que les humains en cas de faible luminosit&#233;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sens aiguis&#233;s.&lt;/b&gt; Les vishkanyas re&#231;oivent un bonus racial de +2 &#224; leurs tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Souplesse.&lt;/b&gt; Les vishkanyas re&#231;oivent un bonus racial de +2 &#224; leurs tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;sistance au poison.&lt;/b&gt; Le vishkanya re&#231;oit un bonus racial &#233;gal &#224; son nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;d&#233;s de vie&lt;/a&gt; aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Utilisation des poisons.&lt;/b&gt; Les vishkanyas sont rompus &#224; l’utilisation des &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt; et ne s’empoisonnent jamais accidentellement lorsqu’ils utilisent ou manipulent du poison.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Toxique.&lt;/b&gt; Un nombre de fois par jour &#233;gal &#224; son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;, le vishkanya peut empoisonner une arme qu’il manie avec sa salive ou son sang toxique (l’emploi de son sang n&#233;cessite que le vishkanya soit bless&#233; lorsqu’il utilise cette capacit&#233;). Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; pour appliquer le venin de cette mani&#232;re.&lt;ul&gt;&lt;li&gt;&lt;i&gt;Venin vishkanya.&lt;/i&gt; Blessure ; &lt;i&gt;JdS&lt;/i&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 10 + 1/2 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;d&#233;s de vie&lt;/a&gt; du vishkanya + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; ; &lt;i&gt;fr&#233;quence&lt;/i&gt; 1/round pendant 6 rounds ; &lt;i&gt;effet&lt;/i&gt; 1d2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; ; &lt;i&gt;gu&#233;rison&lt;/i&gt; 1 r&#233;ussite.&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Apprentissage martial.&lt;/b&gt; Les vishkanyas sont form&#233;s au maniement des &lt;a class=&quot;pagelink&quot; href=&quot;Kukri-(Arme).html&quot; title=&quot;Kukri&quot;&gt;kukris&lt;/a&gt;, des &lt;a class=&quot;pagelink&quot; href=&quot;Sarbacane-(Arme).html&quot; title=&quot;Sarbacane&quot;&gt;sarbacanes&lt;/a&gt; et des &lt;a class=&quot;pagelink&quot; href=&quot;Shurikens-(Arme).html&quot; title=&quot;Shurikens (5)&quot;&gt;shurikens&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues.&lt;/b&gt; Les vishkanyas commencent le jeu en parlant le commun et le vishkanyan. Ceux qui ont une valeur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#233;lev&#233;e peuvent apprendre d’autres langues parmi celles-ci : aklo, commun des profondeurs, draconique, elfique, gobelin et sylvestre.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TRAITSALTERNATIFS&quot; href=&quot;#TRAITSALTERNATIFS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Traits raciaux alternatifs&lt;a class=&quot;headeranchor&quot; id=&quot;Traits_raciaux_alternatifs_6&quot; href=&quot;#Traits_raciaux_alternatifs_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Il est possible de choisir les traits raciaux suivants &#224; la place des traits raciaux existants des vishkanyas. Consultez votre MJ avant de prendre ces nouvelles options.&lt;br /&gt;&lt;br /&gt;&lt;u&gt;&lt;i&gt;Remplace &#171; sens aiguis&#233;s &#187; :&lt;/i&gt;&lt;/u&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Sensuel.&lt;/b&gt; Les vishkanyas ma&#238;trisent l’art d’attirer l’attention sur eux. Ils b&#233;n&#233;ficient d’un bonus de +2 &#224; une des comp&#233;tences de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;. Ce trait racial remplace sens aiguis&#233;s.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;u&gt;&lt;i&gt;Modifie &#171; souplesse &#187; :&lt;/i&gt;&lt;/u&gt;
&lt;ul&gt;&lt;li&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Races de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Races/Races de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;Trompeur.&lt;/b&gt; Les clans vishkanyas qui vivent du cambriolage ou du meurtre d&#39;humains apprennent &#224; distraire leurs cibles aux moments les plus critiques. Ils b&#233;n&#233;ficient d&#39;un bonus racial de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;. Ce trait racial remplace le bonus racial aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;u&gt;&lt;i&gt;Remplace &#171; vision nocturne &#187; :&lt;/i&gt;&lt;/u&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Apparence subtile.&lt;/b&gt; Le vishkanya a des yeux normaux (humains), et sa beaut&#233; est plus conventionnelle. Il b&#233;n&#233;ficie d’un bonus de +4 &#224; ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt; pour para&#238;tre parfaitement humain. Ce trait racial remplace vision nocturne.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt;Bonus alternatifs de classe de pr&#233;dilection&lt;a class=&quot;headeranchor&quot; id=&quot;Bonus_alternatifs_de_classe_de_pr&#233;dilection_7&quot; href=&quot;#Bonus_alternatifs_de_classe_de_pr&#233;dilection_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Chacune de ces r&#233;compenses remplace celle que les joueurs obtenaient normalement en gagnant un niveau dans une &lt;a class=&quot;pagelink&quot; href=&quot;Progression-Des-Personnages.html#CLASSEDEPREDILECTION&quot; title=&quot;Progression des personnages&quot;&gt;classe de pr&#233;dilection&lt;/a&gt;, &#224; savoir 1 point de vie suppl&#233;mentaire ou 1 rang de comp&#233;tence suppl&#233;mentaire. Contrairement &#224; ces r&#233;compenses d’ordre g&#233;n&#233;rique, les r&#233;compenses alternatives se focalisent sur les sp&#233;cificit&#233;s de la classe et sur les tendances g&#233;n&#233;rales d’une race.&lt;br /&gt;&lt;br /&gt;Le personnage choisit son option de classe de pr&#233;dilection quand il gagne un niveau. Ces avantages se cumulent toujours, sauf indication contraire.&lt;br /&gt;&lt;br /&gt;Enfin, &#224; chaque fois que le personnage les choisit, nombre d’avantages alternatifs ajoutent seulement +1/2, +1/3, +1/4 ou +1/6 (au lieu de +1) &#224; un jet ou &#224; une aptitude de classe (comme un ajout au nombre de rages sanguines quotidiennes du sanguin ou au total de points de panache du bretteur). Quand le personnage applique cet avantage &#224; un jet de d&#233;, il arrondit toujours &#224; l’inf&#233;rieur (0 au minimum). Il devra donc en choisir certains &#224; plusieurs reprises avant d’en tirer le moindre b&#233;n&#233;fice.&lt;br /&gt;&lt;br /&gt;Certaines options s’accompagnent d’une limite num&#233;raire fixe, une fois cette limite atteinte, il ne sert plus &#224; rien de choisir l’option qui n’a pas d’effet suppl&#233;mentaire. Le personnage peut toujours choisir une r&#233;compense ordinaire quand il gagne un niveau dans sa classe de pr&#233;dilection (&#224; savoir 1 point de vie ou 1 rang de comp&#233;tence suppl&#233;mentaire).&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;Barde&lt;/a&gt;.&lt;/b&gt; Le barde rajoute +1 &#224; son nombre total de rounds par jour de &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#REPRESENTATIONBARDIQUE&quot; title=&quot;Le barde&quot;&gt;repr&#233;sentation bardique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ensorceleur&lt;/a&gt;.&lt;/b&gt; L&#39;ensorceleur choisit un &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html#LIGNAGE&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;pouvoir de lignage&lt;/a&gt; de niveau 1 normalement utilisable un nombre de fois par jour &#233;gal &#224; 3 + le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. Il rajoute +1/2 &#224; son nombre d’utilisations par jour de ce pouvoir de lignage.
&lt;/td&gt;&lt;td width=&quot;1%&quot;&gt;
&lt;td style=&quot;border-left:1px solid #4b3124&quot; width=&quot;1%&quot;&gt;&lt;/td&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;Roublard&lt;/a&gt;.&lt;/b&gt; Le roublard rajoute +1 &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; lorsqu’il r&#233;siste &#224; une tentative de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Repositionnement.html&quot; title=&quot;repositionnement&quot;&gt;repositionnement&lt;/a&gt;.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_8&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Voici les options accessibles aux vishkanyas, d’autres races adapt&#233;es peuvent s’en servir si le MJ donne son accord.
&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_0&quot; href=&quot;#Dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les vishkanyas ont acc&#232;s &#224; ce don.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
